'use client'

/**
 * /book/[studioSlug]/artist/[artistSlug]
 *
 * Per-artist direct booking page.
 * Resolves the artist by (studio_slug, artist_slug) then renders the studio
 * booking flow pre-filtered to that artist.
 *
 * Reuses the same API endpoints as the studio booking root; the artistId is
 * passed as a URL param when navigating into the service booking step.
 */
import { use } from 'react'
import { useQuery } from '@tanstack/react-query'
import { Skeleton } from '@/components/ui/skeleton'
import { Typography } from '@/components/ui/typography'
import { useRouter } from 'next/navigation'
import { formatCurrency } from '@/lib/utils'
import { TrustBadges } from '@/components/booking/TrustBadges'
import { Clock, ChevronRight, ArrowLeft, X } from 'lucide-react'
import { useState } from 'react'
import type { ArtistPortfolioItem, StyleTag } from '@/lib/supabase/types'
import { StyleTagChips } from '@/components/shared/StyleTagPicker'

interface StudioPublic {
  id: string
  name: string
  slug: string
  brand_color: string | null
  logo_url: string | null
  show_prices?: boolean
}

interface ArtistPublic {
  id: string
  display_name: string
  avatar_url: string | null
  bio: string | null
  specialties: string[]
  profile_bio_public: string | null
  social_instagram: string | null
}

interface ServicePublic {
  id: string
  name: string
  description: string | null
  duration_min: number
  base_price_cents: number
  deposit_cents: number
  deposit_required: boolean
  color: string | null
}

export default function ArtistBookingPage({
  params,
}: {
  params: Promise<{ studioSlug: string; artistSlug: string }>
}) {
  const { studioSlug, artistSlug } = use(params)
  const router = useRouter()

  const { data: studioData, isLoading: studioLoading, error: studioError } = useQuery<{ data: StudioPublic }>({
    queryKey: ['public', 'studio', studioSlug],
    queryFn: async () => {
      const res = await fetch(`/api/public/studios/${studioSlug}`)
      if (!res.ok) throw new Error('Studio not found')
      return res.json() as Promise<{ data: StudioPublic }>
    },
  })

  const studio = studioData?.data

  const { data: artistData, isLoading: artistLoading, error: artistError } = useQuery<{ data: ArtistPublic | null }>({
    queryKey: ['public', 'artist-by-slug', studioSlug, artistSlug],
    queryFn: async () => {
      const res = await fetch(`/api/public/studios/${studioSlug}/artists/${artistSlug}`)
      if (res.status === 404) return { data: null }
      if (!res.ok) throw new Error('Failed to load artist')
      return res.json() as Promise<{ data: ArtistPublic }>

import { NextResponse } from 'next/server'
import { createPublicClient } from '@/lib/supabase/public'
import { publicBookingReadRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

export async function GET(
  req: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params
  const ip = req.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await publicBookingReadRatelimit.limit(ip)
  if (!rl.success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const supabase = createPublicClient()

  try {
    const { data, error } = await supabase
      .from('artist_portfolio_items')
      .select('*')
      .eq('artist_id', id)
      .order('display_order', { ascending: true })

    if (error) {
      logger.error({ error, id }, 'GET /api/public/artists/[id]/portfolio failed')
      return NextResponse.json({ data: [] })
    }

    return NextResponse.json({ data: data ?? [] })
  } catch (err) {
    logger.error({ err, id }, 'GET /api/public/artists/[id]/portfolio unexpected error')
    return NextResponse.json({ data: [] })
  }
}
